function coolUI(){for(let k in cooldowns){let el=document.querySelector(`[data-skill="${k}"] .cd`),btn=document.querySelector(`[data-skill="${k}"]`);if(el)el.textContent=cooldowns[k]>.05?cooldowns[k].toFixed(1):'';if(btn)btn.classList.toggle('disabled',cooldowns[k]>.05)}}
function drawGround(){let horizon=vh*.42;let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#101a1b');sky.addColorStop(.72,'#33413b');sky.addColorStop(1,'#877353');ctx.fillStyle=sky;ctx.fillRect(0,0,vw,vh);let glow=ctx.createRadialGradient(vw*.5,horizon,3,vw*.5,horizon,vw*.48);glow.addColorStop(0,'#e3b46a66');glow.addColorStop(1,'#e3b46a00');ctx.fillStyle=glow;ctx.fillRect(0,0,vw,vh);ctx.fillStyle='#28332b';ctx.fillRect(0,horizon,vw,vh-horizon);let ground=ctx.createLinearGradient(0,horizon,0,vh);ground.addColorStop(0,'#536047');ground.addColorStop(.34,'#353d2f');ground.addColorStop(1,'#151c17');ctx.fillStyle=ground;ctx.fillRect(0,horizon,vw,vh-horizon);ctx.fillStyle='#83734e';ctx.beginPath();ctx.moveTo(vw*.48,horizon);ctx.lineTo(vw*.52,horizon);ctx.lineTo(vw*.89,vh);ctx.lineTo(vw*.11,vh);ctx.fill();ctx.strokeStyle='#c2a66b30';ctx.lineWidth=1;for(let i=1;i<12;i++){let y=horizon+(vh-horizon)*(i/12)**2;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(vw,y);ctx.stroke()}for(let i=-9;i<=9;i++){ctx.beginPath();ctx.moveTo(vw/2+i*4,horizon);ctx.lineTo(vw/2+i*vw*.055,vh);ctx.stroke()}ctx.fillStyle='#18221d';for(let i=0;i<17;i++){let x=i*vw/16,y=horizon+Math.sin(i*9.1)*12;ctx.beginPath();ctx.moveTo(x-42,y);ctx.lineTo(x,y-48-(i%4)*9);ctx.lineTo(x+42,y);ctx.fill()}ctx.fillStyle='#ead39a';ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(vw*.78,vh*.16,15,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
function drawProp(q){let p=project(q.x,q.z);if(p.f<1||p.f>115)return;let s=clamp(p.scale*.25,1,55),ground=p.y;if(q.type==='pine'){ctx.fillStyle='#11181288';ctx.beginPath();ctx.ellipse(p.x,ground,s*1.1,s*.22,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#4a4634';ctx.fillRect(p.x-s*.12,ground-s*2,s*.24,s*2);ctx.fillStyle='#25382e';for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(p.x,ground-s*(q.h*2.7-i*.72));ctx.lineTo(p.x-s*(1.15-i*.24),ground-s*(i*.7));ctx.lineTo(p.x+s*(1.15-i*.24),ground-s*(i*.7));ctx.fill()}}else if(q.type==='stone'){ctx.fillStyle='#11181299';ctx.beginPath();ctx.ellipse(p.x,ground,s,s*.3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#64614d';ctx.beginPath();ctx.moveTo(p.x-s,ground);ctx.lineTo(p.x-s*.72,ground-s*q.h);ctx.lineTo(p.x+s*.15,ground-s*q.h*1.2);ctx.lineTo(p.x+s,ground-s*.45);ctx.lineTo(p.x+s*.8,ground);ctx.fill()}else{ctx.fillStyle='#49372b';ctx.fillRect(p.x-s*.1,ground-s*2,s*.2,s*2);ctx.fillStyle='#ffbb61';ctx.shadowColor='#ffad53';ctx.shadowBlur=s*2.5;ctx.beginPath();ctx.arc(p.x,ground-s*2,s*.3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}}
function drawEnemy(e){let p=project(e.x,e.z);if(p.f<.6||p.f>90)return;let s=clamp(p.scale*.31,2,68),g=p.y,hit=e.hit>0;ctx.fillStyle='#080d0ba8';ctx.beginPath();ctx.ellipse(p.x,g,s*.62,s*.16,0,0,Math.PI*2);ctx.fill();let bob=Math.sin(elapsed*3+e.phase)*s*.035;ctx.save();ctx.translate(p.x,g+bob);ctx.fillStyle=hit?'#f5c27b':'#552f2c';ctx.beginPath();ctx.moveTo(-s*.34,-s*.44);ctx.lineTo(-s*.42,-s*1.22);ctx.lineTo(-s*.2,-s*1.52);ctx.lineTo(0,-s*1.32);ctx.lineTo(s*.2,-s*1.52);ctx.lineTo(s*.42,-s*1.22);ctx.lineTo(s*.34,-s*.44);ctx.closePath();ctx.fill();ctx.fillStyle=hit?'#fff0bd':'#8c4d40';ctx.beginPath();ctx.ellipse(0,-s*1.4,s*.27,s*.32,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffb773';ctx.shadowColor='#ff6c48';ctx.shadowBlur=s*.5;ctx.fillRect(-s*.15,-s*1.46,s*.09,s*.055);ctx.fillRect(s*.06,-s*1.46,s*.09,s*.055);ctx.shadowBlur=0;ctx.strokeStyle='#c18b67';ctx.lineWidth=Math.max(1,s*.07);ctx.beginPath();ctx.moveTo(-s*.28,-s*.88);ctx.lineTo(-s*.62,-s*.54);ctx.moveTo(s*.28,-s*.88);ctx.lineTo(s*.62,-s*.59);ctx.stroke();ctx.restore();let bw=s*.9;ctx.fillStyle='#151511';ctx.fillRect(p.x-bw/2,g-s*1.72,bw,Math.max(2,s*.06));ctx.fillStyle='#d27a67';ctx.fillRect(p.x-bw/2,g-s*1.72,bw*clamp(e.hp/e.max,0,1),Math.max(2,s*.06))}
function drawWorld(){drawGround();let objects=props.map(q=>({z:q.z,fn:()=>drawProp(q)}));for(let e of enemies)if(!e.dead)objects.push({z:e.z,fn:()=>drawEnemy(e)});objects.sort((a,b)=>b.z-a.z);for(let o of objects)o.fn();for(let b of bolts){let a=project(b.x,b.z),t=project(b.tx,b.tz);ctx.strokeStyle='#ffcc78';ctx.shadowColor='#ff9f4d';ctx.shadowBlur=12;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(a.x,vh*.48);ctx.lineTo(t.x,t.y-8);ctx.stroke();ctx.shadowBlur=0}for(let p of particles){let q=project(p.x,p.z);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(q.x,q.y-p.life*14,2+p.life*2,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;let p=nearest(),lock=false;if(p&&p.f<42){let a=Math.atan2(p.e.x-player.x,p.e.z-player.z)-player.yaw;a=Math.atan2(Math.sin(a),Math.cos(a));lock=Math.abs(a)<.24}$('#crosshair').classList.toggle('lock',lock);if(player.guard>0){ctx.strokeStyle='#9dd8da99';ctx.lineWidth=3;ctx.beginPath();ctx.arc(vw/2,vh*.48,28+Math.sin(elapsed*20)*3,0,Math.PI*2);ctx.stroke()}}
function drawMap(){let w=map.clientWidth,h=map.clientHeight;mctx.clearRect(0,0,w,h);mctx.fillStyle='#283c33';mctx.fillRect(0,0,w,h);mctx.strokeStyle='#b8aa7b22';for(let i=1;i<5;i++){mctx.beginPath();mctx.moveTo(w*i/5,0);mctx.lineTo(w*i/5,h);mctx.moveTo(0,h*i/5);mctx.lineTo(w,h*i/5);mctx.stroke()}mctx.fillStyle='#76664c';mctx.beginPath();mctx.moveTo(w*.44,0);mctx.lineTo(w*.54,0);mctx.lineTo(w*.6,h);mctx.lineTo(w*.4,h);mctx.fill();for(let e of enemies)if(!e.dead){let x=w/2+(e.x-player.x)*1.15,y=h/2-(e.z-player.z)*.65;mctx.fillStyle='#e17969';mctx.beginPath();mctx.arc(x,y,3,0,7);mctx.fill()}let px=w/2,py=h/2;mctx.fillStyle='#a5d9ec';mctx.beginPath();mctx.arc(px,py,4,0,7);mctx.fill();mctx.strokeStyle='#a5d9ec';mctx.beginPath();mctx.moveTo(px,py);mctx.lineTo(px+Math.sin(player.yaw)*10,py-Math.cos(player.yaw)*10);mctx.stroke()}

