 function cast(){if(!active||over||cooldowns.slash>0)return;let p=nearest();let picked=null;if(p){let angle=Math.atan2(p.e.x-player.x,p.e.z-player.z)-player.yaw;angle=Math.atan2(Math.sin(angle),Math.cos(angle));if(Math.abs(angle)<.24&&p.f<42)picked=p.e}cooldowns.slash=.34;player.mp=Math.max(0,player.mp-2);if(picked){picked.hp-=34;picked.hit=.22;bolts.push({x:player.x,z:player.z,tx:picked.x,tz:picked.z,life:.16});addBurst(picked.x,picked.z,'#ffc56c',7);if(picked.hp<=0)kill(picked)}else{bolts.push({x:player.x,z:player.z,tx:player.x+Math.sin(player.yaw)*24,tz:player.z+Math.cos(player.yaw)*24,life:.18})}coolUI()}
 function kill(e){if(e.dead)return;e.dead=true;kills++;$('#kills').textContent=kills;setMP(player.mp+16);addBurst(e.x,e.z,'#df7566',18);say('WRAITH BANISHED · +16 FOCUS')}
